function renderPalettes(){E('customQuestionPalette').innerHTML=customTypes.map(function(x){return paletteButton(x,'data-add-custom',x.type,false)}).join('');E('standardPalette').innerHTML=standards.map(function(x){return paletteButton(x,'data-add-standard',x.key,hasStandard(x.key))}).join('');E('actionPalette').innerHTML=actions.map(function(x){return paletteButton(x,'data-add-action',x.type,hasAction(x.type))}).join('');document.querySelectorAll('[data-add-custom]').forEach(function(b){b.onclick=function(){addCustom(b.getAttribute('data-add-custom'))}});document.querySelectorAll('[data-add-standard]').forEach(function(b){b.onclick=function(){addStandard(b.getAttribute('data-add-standard'))}});document.querySelectorAll('[data-add-action]').forEach(function(b){b.onclick=function(){addAction(b.getAttribute('data-add-action'))}});icons()}
