function renderSettings(){if(!state.form)return;E('settingsTitle').value=state.form.name||'';E('settingsDescription').value=state.form.description||'';E('settingsPages').checked=Number(state.form.form_pages||0)===1;E('settingsRequestDefault').checked=Number(state.form.is_request_default||0)===1;E('settingsBookingDefault').checked=Number(state.form.is_booking_default||0)===1;E('settingsApproval').checked=Number(state.form.require_booking_approval||0)===1;E('settingsServiceArea').checked=Number(state.form.service_area_enabled||0)===1;E('bookingDefaultRow').classList.toggle('rbb-hidden',state.form.form_type==='request');var b=state.form.booking||{};E('earliestDays').value=b.earliest_availability_days==null?1:b.earliest_availability_days;E('maxDays').value=b.max_booking_days_ahead==null?30:b.max_booking_days_ahead;var enabled=hasBooking();E('bookingAvailabilityNotice').textContent=enabled?'Specify when customers can choose an appointment time.':"Unavailable because this form currently doesn't include online booking or assessments.";E('efficientNotice').textContent=enabled?'Control spacing and travel-aware scheduling for online bookings.':"Unavailable because this form currently doesn't include online booking or assessments.";document.querySelectorAll('#settingsPanel .rbb-accordion input').forEach(function(x){if(x.id!=='gaCode')x.disabled=!enabled&&(['earliestDays','maxDays'].indexOf(x.id)>=0||x.name==='efficientMode')});renderChips(enabled);var ef=state.form.efficient_scheduling||{};var radio=document.querySelector('input[name="efficientMode"][value="'+(ef.mode||'fixed_buffer')+'"]');if(radio)radio.checked=true;E('gaCode').value=state.form.google_analytics_code||'';E('publicUrl').value=state.form.public_url||'';E('embedCode').value=state.form.embed_code||'';renderGoogle()}
function renderChips(enabled){var b=state.form.booking||{},ef=state.form.efficient_scheduling||{};E('intervalChips').innerHTML=[30,60,120,180,240].map(function(v){return '<button type="button" class="rbb-chip '+(Number(b.booking_interval_minutes||30)===v?'active':'')+'" data-interval="'+v+'" '+(!enabled?'disabled':'')+'>'+ (v<60?v+' minutes':(v/60)+' hour'+(v>60?'s':''))+'</button>'}).join('');E('driveChips').innerHTML=[15,30,45,60].map(function(v){return '<button type="button" class="rbb-chip '+(Number(ef.drive_time_limit_minutes||30)===v?'active':'')+'" data-drive="'+v+'" '+(!enabled?'disabled':'')+'>'+v+' minutes</button>'}).join('');E('bufferChips').innerHTML=[15,30,60].map(function(v){return '<button type="button" class="rbb-chip '+(Number(ef.fixed_buffer_minutes||30)===v?'active':'')+'" data-buffer="'+v+'" '+(!enabled?'disabled':'')+'>'+v+' minutes</button>'}).join('');document.querySelectorAll('[data-interval]').forEach(function(x){x.onclick=function(){state.form.booking.booking_interval_minutes=Number(x.getAttribute('data-interval'));renderSettings()}});document.querySelectorAll('[data-drive]').forEach(function(x){x.onclick=function(){state.form.efficient_scheduling.drive_time_limit_minutes=Number(x.getAttribute('data-drive'));renderSettings()}});document.querySelectorAll('[data-buffer]').forEach(function(x){x.onclick=function(){state.form.efficient_scheduling.fixed_buffer_minutes=Number(x.getAttribute('data-buffer'));renderSettings()}})}
