function syncSettingsToState(){state.form.name=E('settingsTitle').value.trim()||state.form.name;state.form.description=E('settingsDescription').value;state.form.form_pages=E('settingsPages').checked?1:0;state.form.is_request_default=E('settingsRequestDefault').checked?1:0;state.form.is_booking_default=E('settingsBookingDefault').checked?1:0;state.form.require_booking_approval=E('settingsApproval').checked?1:0;state.form.service_area_enabled=E('settingsServiceArea').checked?1:0;state.form.booking.earliest_availability_days=Math.max(0,Number(E('earliestDays').value||0));state.form.booking.max_booking_days_ahead=Math.max(1,Number(E('maxDays').value||30));state.form.efficient_scheduling.mode=(document.querySelector('input[name="efficientMode"]:checked')||{value:'fixed_buffer'}).value;state.form.google_analytics_code=E('gaCode').value.trim();E('builderTitle').textContent='Edit '+state.form.name}
