function save(){syncSettingsToState();syncActionsFromItems();state.form.confirmation_title=E('confirmTitleCanvas')?E('confirmTitleCanvas').value:state.form.confirmation_title;state.form.confirmation_message=E('confirmMessageCanvas')?E('confirmMessageCanvas').value:state.form.confirmation_message;state.form.confirmation_url=E('confirmUrlCanvas')?E('confirmUrlCanvas').value:state.form.confirmation_url;var x=fd('save');x.append('id',CFG.id);x.append('name',state.form.name);x.append('description',state.form.description||'');x.append('builder_json',JSON.stringify(state.builder));x.append('booking_json',JSON.stringify(state.form.booking||{}));x.append('efficient_scheduling_json',JSON.stringify(state.form.efficient_scheduling||{}));x.append('google_business_profile_json',JSON.stringify(state.form.google_business_profile||{}));x.append('tracking_json',JSON.stringify(state.form.tracking||{}));x.append('form_pages',state.form.form_pages?'1':'0');x.append('is_request_default',state.form.is_request_default?'1':'0');x.append('is_booking_default',state.form.is_booking_default?'1':'0');x.append('require_booking_approval',state.form.require_booking_approval?'1':'0');x.append('service_area_enabled',state.form.service_area_enabled?'1':'0');x.append('confirmation_title',state.form.confirmation_title||'');x.append('confirmation_message',state.form.confirmation_message||'');x.append('confirmation_url',state.form.confirmation_url||'');x.append('google_analytics_code',state.form.google_analytics_code||'');var btn=E('saveBtn'),old=btn.innerHTML;btn.disabled=true;btn.textContent='Saving...';req(x).then(function(d){toast('success',d.message);setTimeout(function(){location.href='request-booking-settings.php'},300)}).catch(function(e){toast('error',e.message);btn.disabled=false;btn.innerHTML=old;icons()})}
function openArea(){var a=state.serviceArea||{};E('areaId').value=a.id||0;E('areaAddress').value=a.address_text||'';E('areaLat').value=a.latitude==null?'':a.latitude;E('areaLng').value=a.longitude==null?'':a.longitude;E('areaRadius').value=a.radius_km?Math.round(Number(a.radius_km)):25;E('areaRadiusValue').textContent=E('areaRadius').value;E('areaModal').classList.add('open');setTimeout(initMap,80);icons()}
function closeArea(){E('areaModal').classList.remove('open')}
function initMap(){if(!(window.google&&google.maps)){E('builderMapNote').textContent='Google Maps is not configured. Address and radius can still be saved; set GOOGLE_MAPS_API_KEY to enable map search.';return}if(state.map)return;var lat=Number(E('areaLat').value)||20.5937,lng=Number(E('areaLng').value)||78.9629;state.map=new google.maps.Map(E('builderMap'),{center:{lat:lat,lng:lng},zoom:E('areaLat').value?10:4,mapTypeControl:false,streetViewControl:false,fullscreenControl:false});state.marker=new google.maps.Marker({map:state.map,position:{lat:lat,lng:lng},draggable:true});state.circle=new google.maps.Circle({map:state.map,center:{lat:lat,lng:lng},radius:Number(E('areaRadius').value)*1000,fillOpacity:.15,strokeOpacity:.55,strokeWeight:2});state.geocoder=new google.maps.Geocoder();state.marker.addListener('dragend',function(){var p=state.marker.getPosition();E('areaLat').value=p.lat();E('areaLng').value=p.lng();state.circle.setCenter(p)});E('areaAddress').addEventListener('change',function(){state.geocoder.geocode({address:E('areaAddress').value},function(res,status){if(status==='OK'&&res[0]){var p=res[0].geometry.location;E('areaLat').value=p.lat();E('areaLng').value=p.lng();state.map.setCenter(p);state.map.setZoom(10);state.marker.setPosition(p);state.circle.setCenter(p)}else toast('error','Address could not be located.')})})}
